// Find the smallest x in [1, 2_000_000_000] with x >= target.
function firstAtLeast(target) {
  let lo = 1, hi = 2000000000, ans = -1, iters = 0;
  while (lo <= hi) {
    if (++iters > 200) return 'INFINITE_LOOP'; // safety guard so this is runnable
    const mid = (lo + hi) >> 1;   // BUG: `>>` coerces to 32-bit; lo+hi past 2^31 goes negative
