function countReachable(start, adj, n) {
  const visited = new Array(n).fill(false);
  const queue = [start];
  let count = 0;
  while (queue.length > 0) {
    const node = queue.shift();
    visited[node] = true;   // BUG: marked on dequeue, not on enqueue
    count++;
    for (const nei of adj[node]) {
      if (!visited[nei]) queue.push(nei); // nei still unmarked when two parents enqueue it
    }
  }
  return count;
}

