}

// node = { val, next }
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next;   // BUG: should be fast.next.next
    if (slow === fast) return true; // slow and fast move in lockstep -> always equal
  }
  return false;
}

function climbStairs(n) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = 0;   // BUG: should be 1 (one way to stand at the ground)
  if (n >= 1) dp[1] = 1;
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(0); // BUG: unreachable states must be Infinity
  dp[0] = 0;
  for (let a = 1; a <= amount; a++) {
    for (const c of coins) {
      if (a - c >= 0) dp[a] = Math.min(dp[a], dp[a - c] + 1);
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

